use std::collections::HashMap;
use std::str;

/// Cloud infrastructure SDK - Request routing module
/// Handles requests coming through a reverse proxy (e.g., nginx, envoy)
/// The proxy normalizes most headers but passes through the request path as-is.

#[derive(Debug, Clone)]
pub struct CloudRequest {
    pub method: String,
    pub path: String,
    pub headers: HashMap<String, String>,
    pub body: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Permission {
    ReadOnly,
    ReadWrite,
    Admin,
}

#[derive(Debug)]
pub struct AuthContext {
    pub user_id: String,
    pub permission: Permission,
    pub tenant_id: String,
}

/// Decodes percent-encoded bytes in a path segment.
/// Returns the decoded string for authorization checks.
fn decode_path_segment(segment: &str) -> String {
    let bytes = segment.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hex_str = &segment[i+1..i+3];
            if let Ok(byte_val) = u8::from_str_radix(hex_str, 16) {
                decoded.push(byte_val);
                i += 3;
                continue;
            }
        }
        decoded.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&decoded).to_string()
}

/// Normalizes path by resolving dot segments (RFC 3986 Section 5.2.4)
/// This runs AFTER the authorization check to prepare the path for routing.
fn normalize_path(path: &str) -> String {
    let segments: Vec<&str> = path.split('/').collect();
    let mut output: Vec<&str> = Vec::new();
    for seg in &segments {
        match *seg {
            "." => continue,
            ".." => { output.pop(); },
            s => output.push(s),
        }
    }
    let result = output.join("/");
    if result.starts_with('/') {
        result
    } else {
        format!("/{}", result)
    }
}

/// Authorization check: determines if the request path is within
/// the tenant's allowed namespace. The path format is:
/// /api/v1/tenants/{tenant_id}/resources/...
fn authorize_request(auth: &AuthContext, raw_path: &str) -> bool {
    // Admin can access everything
    if auth.permission == Permission::Admin {
        return true;
    }

    // Extract tenant from the raw path for authorization
    let segments: Vec<&str> = raw_path.split('/').filter(|s| !s.is_empty()).collect();

    // Expected: ["api", "v1", "tenants", "{tenant_id}", "resources", ...]
    if segments.len() < 4 {
        return false;
    }

    if segments[0] != "api" || segments[1] != "v1" || segments[2] != "tenants" {
        return false;
    }

    let path_tenant = segments[3];

    // Check tenant isolation - compare decoded tenant from path with auth context
    // The reverse proxy already decoded the path once, so we decode again
    // to handle double-encoding edge cases from legacy clients
    let decoded_tenant = decode_path_segment(path_tenant);

    decoded_tenant == auth.tenant_id
}

/// Routes the request to the appropriate backend handler.
/// The path is normalized AFTER authorization to resolve any relative segments.
fn route_request(request: &CloudRequest, auth: &AuthContext) -> Result<String, String> {
    // Step 1: Authorize against the raw path
    if !authorize_request(auth, &request.path) {
        return Err("403 Forbidden: tenant isolation violation".to_string());
    }

    // Step 2: Decode the path for routing
    let decoded_path = decode_path_segment(&request.path);

    // Step 3: Normalize the decoded path (resolve ../ etc)
    let normalized = normalize_path(&decoded_path);

    // Step 4: Route to backend based on normalized path
    Ok(format!("Routed to backend: {}", normalized))
}

/// Simulates the reverse proxy behavior - it passes the raw URI through
/// but validates it doesn't contain obvious traversal in the raw form.
fn reverse_proxy_filter(raw_uri: &str) -> Result<String, String> {
    // The proxy blocks raw ".." segments but allows encoded forms
    // since backends are expected to handle decoding safely
    let segments: Vec<&str> = raw_uri.split('/').collect();
    for seg in &segments {
        if *seg == ".." || *seg == "." {
            return Err("400 Bad Request: path traversal blocked by proxy".to_string());
        }
    }
    Ok(raw_uri.to_string())
}

pub fn handle_incoming_request(
    method: &str,
    raw_uri: &str,
    headers: HashMap<String, String>,
    body: Vec<u8>,
    auth: AuthContext,
) -> Result<String, String> {
    // Proxy filtering
    let filtered_path = reverse_proxy_filter(raw_uri)?;

    let request = CloudRequest {
        method: method.to_string(),
        path: filtered_path,
        headers,
        body,
    };

    route_request(&request, &auth)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_access() {
        let auth = AuthContext {
            user_id: "user1".to_string(),
            permission: Permission::ReadWrite,
            tenant_id: "tenant-abc".to_string(),
        };
        let result = handle_incoming_request(
            "GET",
            "/api/v1/tenants/tenant-abc/resources/vms",
            HashMap::new(),
            vec![],
            auth,
        );
        assert!(result.is_ok());
    }

    #[test]
    fn test_cross_tenant_blocked() {
        let auth = AuthContext {
            user_id: "user1".to_string(),
            permission: Permission::ReadWrite,
            tenant_id: "tenant-abc".to_string(),
        };
        let result = handle_incoming_request(
            "GET",
            "/api/v1/tenants/tenant-xyz/resources/vms",
            HashMap::new(),
            vec![],
            auth,
        );
        assert!(result.is_err());
    }

    #[test]
    fn test_encoding_bypass_attempt() {
        // This demonstrates the vulnerability:
        // Path: /api/v1/tenants/tenant-abc/resources/%2e%2e/tenants/tenant-xyz/resources/secrets
        // Authorization sees "tenant-abc" at segments[3] -> passes
        // After decode + normalize: /api/v1/tenants/tenant-xyz/resources/secrets
        let auth = AuthContext {
            user_id: "attacker".to_string(),
            permission: Permission::ReadWrite,
            tenant_id: "tenant-abc".to_string(),
        };
        let result = handle_incoming_request(
            "GET",
            "/api/v1/tenants/tenant-abc/resources/%2e%2e/%2e%2e/tenants/tenant-xyz/resources/secrets",
            HashMap::new(),
            vec![],
            auth,
        );
        // BUG: This should be Err but passes authorization
        assert!(result.is_ok());
    }
}
